use std::env;
use std::fs;
use std::io::{self, Read};
use std::process;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Mode {
    SyntaxSuggest,
    Syntax,
    Suggest,
    Transform,
    Check,
    Replace,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DiffKind {
    Unchanged,
    Added,
    Deleted,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SyntaxKind {
    None,
    Command,       // 38;2;192;0;128
    Keyword,       // 1
    Variable,      // 38;2;63;127;207
    VarAssignName, // 38;2;0;127;255
    SingleQuote,   // 38;2;255;204;85
    DoubleQuote,   // 38;2;255;0;0
    Arithmetic,    // 38;2;192;0;192
    Comment,       // 1;3;38;2;120;144;96
    Heredoc,       // 38;2;128;32;0
}

#[derive(Debug, Clone)]
struct OutputChunk {
    text: String,
    diff: DiffKind,
    syntax: SyntaxKind,
}

fn fg_style_code(syn: SyntaxKind) -> Option<&'static str> {
    match syn {
        SyntaxKind::None => None,
        SyntaxKind::Command => Some("38;2;192;0;128"),
        SyntaxKind::Keyword => Some("1"),
        SyntaxKind::Variable => Some("38;2;63;127;207"),
        SyntaxKind::VarAssignName => Some("38;2;0;127;255"),
        SyntaxKind::SingleQuote => Some("38;2;255;204;85"),
        SyntaxKind::DoubleQuote => Some("38;2;255;0;0"),
        SyntaxKind::Arithmetic => Some("38;2;192;0;192"),
        SyntaxKind::Comment => Some("1;3;38;2;120;144;96"),
        SyntaxKind::Heredoc => Some("38;2;128;32;0"),
    }
}

fn render_chunks(chunks: &[OutputChunk], mode: Mode) -> String {
    let mut out = String::new();
    let mut current_bg: Option<DiffKind> = None;
    let mut current_fg: SyntaxKind = SyntaxKind::None;

    for chunk in chunks {
        if chunk.text.is_empty() {
            continue;
        }

        if mode == Mode::Transform || mode == Mode::Check || mode == Mode::Replace {
            if chunk.diff != DiffKind::Deleted {
                out.push_str(&chunk.text);
            }
            continue;
        }

        let (bg, fg) = match mode {
            Mode::Transform | Mode::Check | Mode::Replace => (None, SyntaxKind::None),
            Mode::Suggest => (
                match chunk.diff {
                    DiffKind::Unchanged => None,
                    DiffKind::Added => Some(DiffKind::Added),
                    DiffKind::Deleted => Some(DiffKind::Deleted),
                },
                SyntaxKind::None,
            ),
            Mode::Syntax => {
                if chunk.diff == DiffKind::Deleted {
                    continue;
                }
                (None, chunk.syntax)
            }
            Mode::SyntaxSuggest => (
                match chunk.diff {
                    DiffKind::Unchanged => None,
                    DiffKind::Added => Some(DiffKind::Added),
                    DiffKind::Deleted => Some(DiffKind::Deleted),
                },
                chunk.syntax,
            ),
        };

        if bg != current_bg || fg != current_fg {
            if bg.is_none() && fg == SyntaxKind::None {
                out.push_str("\x1b[m");
            } else {
                match bg {
                    Some(DiffKind::Added) => {
                        out.push_str("\x1b[0;42m");
                        if let Some(fg_code) = fg_style_code(fg) {
                            out.push_str("\x1b[0;");
                            out.push_str(fg_code);
                            out.push('m');
                        }
                    }
                    Some(DiffKind::Deleted) => {
                        out.push_str("\x1b[0;41m");
                        if let Some(fg_code) = fg_style_code(fg) {
                            out.push_str("\x1b[0;");
                            out.push_str(fg_code);
                            out.push('m');
                        }
                    }
                    None => {
                        if let Some(fg_code) = fg_style_code(fg) {
                            out.push_str("\x1b[0;");
                            out.push_str(fg_code);
                            out.push('m');
                        }
                    }
                    _ => {}
                }
            }
            current_bg = bg;
            current_fg = fg;
        }

        out.push_str(&chunk.text);
    }

    if (mode == Mode::Syntax || mode == Mode::Suggest || mode == Mode::SyntaxSuggest)
        && (current_bg.is_some() || current_fg != SyntaxKind::None)
    {
        out.push_str("\x1b[m");
    }

    out
}

const HELP_TEXT: &str = "\
Shellharden: The corrective bash syntax highlighter.

Usage:
\tshellharden [options] [files]
\tcat files | shellharden [options] ''

Shellharden is a syntax highlighter and a tool to semi-automate the rewriting
of scripts to ShellCheck conformance, mainly focused on quoting.

The default mode of operation is like `cat`, but with syntax highlighting in
foreground colors and suggestive changes in background colors.

Options:
\t--suggest         Output a colored diff suggesting changes.
\t--syntax          Output syntax highlighting with ANSI colors.
\t--syntax-suggest  Diff with syntax highlighting (default mode).
\t--transform       Output suggested changes.
\t--check           No output; exit with 2 if changes are suggested.
\t--replace         Replace file contents with suggested changes.
\t--                Don't treat further arguments as options.
\t-h|--help         Show help text.
\t--version         Show version.

The changes suggested by Shellharden inhibits word splitting and indirect
pathname expansion. This will make your script ShellCheck compliant in terms of
quoting. Whether your script will work afterwards is a different question:
If your script was using those features on purpose, it obviously won't anymore!

Every script is possible to write without using word splitting or indirect
pathname expansion, but it may involve doing things differently.
See the accompanying file how_to_do_things_safely_in_bash.md or online:
https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md
\n";

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut mode = Mode::SyntaxSuggest;
    let mut files = Vec::new();
    let mut parse_options = true;

    for arg in args.into_iter().skip(1) {
        if parse_options && arg == "--" {
            parse_options = false;
            continue;
        }
        if parse_options && arg.starts_with('-') && !arg.is_empty() {
            match arg.as_str() {
                "-h" | "--help" => {
                    print!("{}", HELP_TEXT);
                }
                "--version" => {
                    println!("4.3.1");
                }
                "--suggest" => mode = Mode::Suggest,
                "--syntax" => mode = Mode::Syntax,
                "--syntax-suggest" => mode = Mode::SyntaxSuggest,
                "--transform" => mode = Mode::Transform,
                "--check" => mode = Mode::Check,
                "--replace" => mode = Mode::Replace,
                _ => {
                    eprintln!("{}: No such option.", arg);
                    process::exit(3);
                }
            }
        } else {
            files.push(arg);
        }
    }

    if files.is_empty() {
        process::exit(0);
    }

    let mut exit_code = 0;

    for path in files {
        let (content, display_path) = if path.is_empty() {
            let mut stdin_str = String::new();
            if let Err(err) = io::stdin().read_to_string(&mut stdin_str) {
                eprintln!(": {}", err);
                exit_code = 1;
                continue;
            }
            (stdin_str, "".to_string())
        } else {
            match fs::read_to_string(&path) {
                Ok(s) => (s, path.clone()),
                Err(err) => {
                    eprintln!("{}: {}", path, err);
                    exit_code = 1;
                    continue;
                }
            }
        };

        let (chunks, err_msg) = parse_and_transform(&display_path, &content);

        if let Some(err) = err_msg {
            eprint!("{}", err);
            exit_code = 1;
            if mode != Mode::Check {
                let rendered = render_chunks(&chunks, mode);
                print!("{}", rendered);
            }
            continue;
        }

        let transformed = render_chunks(&chunks, Mode::Transform);
        let has_changes = transformed != content;

        if mode == Mode::Check {
            if has_changes {
                process::exit(2);
            }
        } else if mode == Mode::Replace {
            if path.is_empty() {
                print!("{}", transformed);
            } else if has_changes {
                if let Err(err) = fs::write(&path, &transformed) {
                    eprintln!("{}: {}", path, err);
                    exit_code = 1;
                }
            }
        } else {
            let rendered = render_chunks(&chunks, mode);
            print!("{}", rendered);
        }
    }

    process::exit(exit_code);
}

fn is_keyword(w: &str) -> bool {
    matches!(
        w,
        "if" | "then"
            | "else"
            | "elif"
            | "fi"
            | "for"
            | "do"
            | "done"
            | "while"
            | "until"
            | "case"
            | "esac"
            | "function"
            | "select"
            | "{"
            | "}"
            | "export"
            | "local"
            | "readonly"
            | "declare"
    )
}

fn parse_and_transform(path: &str, input: &str) -> (Vec<OutputChunk>, Option<String>) {
    let mut chunks = Vec::new();
    let bytes = input.as_bytes();
    let mut i = 0;
    let len = bytes.len();
    let mut command_pos = true;
    let mut scope_stack: Vec<&'static str> = Vec::new();

    while i < len {
        // Check for Syntactic Pitfall ($10, $00, $01)
        if bytes[i] == b'$' && i + 2 < len && bytes[i + 1].is_ascii_digit() && bytes[i + 2].is_ascii_digit() {
            let line_start = input[..i].rfind('\n').map(|p| p + 1).unwrap_or(0);
            let line_end = input[i..].find('\n').map(|p| i + p).unwrap_or(len);
            let line_text = &input[line_start..line_end];
            let col = i - line_start;
            let mut num_end = i + 1;
            while num_end < len && bytes[num_end].is_ascii_digit() {
                num_end += 1;
            }
            let pitfall_len = num_end - i;
            let carets = format!("{}{}", " ".repeat(col), "^".repeat(pitfall_len));

            let msg = format!(
                "{}: Unsupported syntax: Syntactic pitfall\n{}\n{}\nThis does not mean what it looks like. You may be forgiven to think that the full string of numerals is the variable name. Only the fist is.\n\nTry this and be shocked: f() {{ echo \"$9\" \"$10\"; }}; f a b c d e f g h i j\n\nHere is where braces should be used to disambiguate, e.g. \"${{10}}\" vs \"${{1}}0\".\n\nSyntactic pitfalls are deemed too dangerous to fix automatically\n(the purpose of Shellharden is to fix vulnerable code – code that mostly does what it looks like, as opposed to code that never does what it looks like):\n* Fixing what it does would be 100% subtle and might slip through code review unnoticed.\n* Fixing its look would make a likely bug look intentional.\n",
                path, line_text, carets
            );
            return (chunks, Some(msg));
        }

        // Comment / Shebang
        if bytes[i] == b'#' && scope_stack.is_empty() {
            let start = i;
            while i < len && bytes[i] != b'\n' {
                i += 1;
            }
            chunks.push(OutputChunk {
                text: input[start..i].to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::Comment,
            });
            continue;
        }

        // Double quotes
        if bytes[i] == b'"' && scope_stack.last() != Some(&"single_quote") {
            if scope_stack.last() == Some(&"double_quote") {
                scope_stack.pop();
                chunks.push(OutputChunk {
                    text: "\"".to_string(),
                    diff: DiffKind::Unchanged,
                    syntax: SyntaxKind::DoubleQuote,
                });
            } else {
                scope_stack.push("double_quote");
                chunks.push(OutputChunk {
                    text: "\"".to_string(),
                    diff: DiffKind::Unchanged,
                    syntax: SyntaxKind::DoubleQuote,
                });
            }
            i += 1;
            continue;
        }

        // Single quotes
        if bytes[i] == b'\'' && scope_stack.last() != Some(&"double_quote") {
            if scope_stack.last() == Some(&"single_quote") {
                scope_stack.pop();
                chunks.push(OutputChunk {
                    text: "'".to_string(),
                    diff: DiffKind::Unchanged,
                    syntax: SyntaxKind::SingleQuote,
