                                text: "$".to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "{".to_string(),
                                diff: DiffKind::Deleted,
