                        i += 3;
                        let mut paren_count = 2;
                        while i < len && paren_count > 0 {
                            if bytes[i] == b'(' {
                                paren_count += 1;
                            } else if bytes[i] == b')' {
                                paren_count -= 1;
                            }
                            i += 1;
