                        if orig_var.starts_with("${") && orig_var.ends_with('}') && !needs_braces {
                            let var_name = &orig_var[2..orig_var.len() - 1];
                            chunks.push(OutputChunk {
                                text: "$".to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "{".to_string(),
                                diff: DiffKind::Deleted,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: var_name.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "}".to_string(),
                                diff: DiffKind::Deleted,
                                syntax: SyntaxKind::Variable,
