use std::env;
use std::fs;
use std::io::{self, Read};
use std::process;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Mode {
    SyntaxSuggest,
    Syntax,
    Suggest,
    Transform,
    Check,
    Replace,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DiffKind {
    Unchanged,
    Added,
    Deleted,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SyntaxKind {
    None,
    Command,       // 38;2;192;0;128
    Keyword,       // 1
    Variable,      // 38;2;63;127;207
    VarAssignName, // 38;2;0;127;255
    SingleQuote,   // 38;2;255;204;85
    DoubleQuote,   // 38;2;255;0;0
    Arithmetic,    // 38;2;192;0;192
    Comment,       // 1;3;38;2;120;144;96
    Heredoc,       // 38;2;128;32;0
}

#[derive(Debug, Clone)]
struct OutputChunk {
    text: String,
    diff: DiffKind,
    syntax: SyntaxKind,
}

fn fg_style_code(syn: SyntaxKind) -> Option<&'static str> {
    match syn {
        SyntaxKind::None => None,
        SyntaxKind::Command => Some("38;2;192;0;128"),
        SyntaxKind::Keyword => Some("1"),
        SyntaxKind::Variable => Some("38;2;63;127;207"),
        SyntaxKind::VarAssignName => Some("38;2;0;127;255"),
        SyntaxKind::SingleQuote => Some("38;2;255;204;85"),
        SyntaxKind::DoubleQuote => Some("38;2;255;0;0"),
        SyntaxKind::Arithmetic => Some("38;2;192;0;192"),
        SyntaxKind::Comment => Some("1;3;38;2;120;144;96"),
        SyntaxKind::Heredoc => Some("38;2;128;32;0"),
    }
}

fn render_chunks(chunks: &[OutputChunk], mode: Mode) -> String {
    let mut out = String::new();
    let mut current_bg: Option<DiffKind> = None;
    let mut current_fg: SyntaxKind = SyntaxKind::None;

    for chunk in chunks {
        if chunk.text.is_empty() {
            continue;
        }

        match mode {
            Mode::Syntax => {
                if chunk.diff == DiffKind::Added {
                    continue;
                }
            }
            Mode::Transform | Mode::Check | Mode::Replace => {
                if chunk.diff == DiffKind::Deleted {
                    continue;
                }
                out.push_str(&chunk.text);
                continue;
            }
            _ => {}
        }

        let bg = match mode {
            Mode::Suggest | Mode::SyntaxSuggest => match chunk.diff {
                DiffKind::Unchanged => None,
                DiffKind::Added => Some(DiffKind::Added),
                DiffKind::Deleted => Some(DiffKind::Deleted),
            },
            _ => None,
        };

        let fg = match mode {
            Mode::Suggest => SyntaxKind::None,
            Mode::Syntax => chunk.syntax,
            Mode::SyntaxSuggest => {
                if chunk.diff == DiffKind::Unchanged {
                    chunk.syntax
                } else {
                    SyntaxKind::None
                }
            }
            _ => SyntaxKind::None,
        };

        if bg != current_bg || fg != current_fg {
            if bg.is_none() && fg == SyntaxKind::None {
                out.push_str("\x1b[m");
            } else {
                match bg {
                    Some(DiffKind::Added) => {
                        out.push_str("\x1b[0;42m");
                        if let Some(fg_code) = fg_style_code(fg) {
                            out.push_str("\x1b[0;");
                            out.push_str(fg_code);
                            out.push('m');
                        }
                    }
                    Some(DiffKind::Deleted) => {
                        out.push_str("\x1b[0;41m");
                        if let Some(fg_code) = fg_style_code(fg) {
                            out.push_str("\x1b[0;");
                            out.push_str(fg_code);
                            out.push('m');
                        }
                    }
                    None => {
                        if let Some(fg_code) = fg_style_code(fg) {
                            out.push_str("\x1b[0;");
                            out.push_str(fg_code);
                            out.push('m');
                        }
                    }
                    _ => {}
                }
            }
            current_bg = bg;
            current_fg = fg;
        }

        out.push_str(&chunk.text);
    }

    if (mode == Mode::Syntax || mode == Mode::Suggest || mode == Mode::SyntaxSuggest)
        && (current_bg.is_some() || current_fg != SyntaxKind::None)
    {
        out.push_str("\x1b[m");
    }

    out
}

const HELP_TEXT: &str = "\
Shellharden: The corrective bash syntax highlighter.

Usage:
\tshellharden [options] [files]
\tcat files | shellharden [options] ''

Shellharden is a syntax highlighter and a tool to semi-automate the rewriting
of scripts to ShellCheck conformance, mainly focused on quoting.

The default mode of operation is like `cat`, but with syntax highlighting in
foreground colors and suggestive changes in background colors.

Options:
\t--suggest         Output a colored diff suggesting changes.
\t--syntax          Output syntax highlighting with ANSI colors.
\t--syntax-suggest  Diff with syntax highlighting (default mode).
\t--transform       Output suggested changes.
\t--check           No output; exit with 2 if changes are suggested.
\t--replace         Replace file contents with suggested changes.
\t--                Don't treat further arguments as options.
\t-h|--help         Show help text.
\t--version         Show version.

The changes suggested by Shellharden inhibits word splitting and indirect
pathname expansion. This will make your script ShellCheck compliant in terms of
quoting. Whether your script will work afterwards is a different question:
If your script was using those features on purpose, it obviously won't anymore!

Every script is possible to write without using word splitting or indirect
pathname expansion, but it may involve doing things differently.
See the accompanying file how_to_do_things_safely_in_bash.md or online:
https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md
\n";

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut mode = Mode::SyntaxSuggest;
    let mut files = Vec::new();
    let mut parse_options = true;

    for arg in args.into_iter().skip(1) {
        if parse_options && arg == "--" {
            parse_options = false;
            continue;
        }
        if parse_options && arg.starts_with('-') && !arg.is_empty() {
            match arg.as_str() {
                "-h" | "--help" => {
                    print!("{}", HELP_TEXT);
                }
                "--version" => {
                    println!("4.3.1");
                }
                "--suggest" => mode = Mode::Suggest,
                "--syntax" => mode = Mode::Syntax,
                "--syntax-suggest" => mode = Mode::SyntaxSuggest,
                "--transform" => mode = Mode::Transform,
                "--check" => mode = Mode::Check,
                "--replace" => mode = Mode::Replace,
                _ => {
                    eprintln!("{}: No such option.", arg);
                    process::exit(3);
                }
            }
        } else {
            files.push(arg);
        }
    }

    if files.is_empty() {
        process::exit(0);
    }

    let mut exit_code = 0;

    for path in files {
        let (content, display_path) = if path.is_empty() {
            let mut stdin_str = String::new();
            if let Err(err) = io::stdin().read_to_string(&mut stdin_str) {
                eprintln!(": {}", err);
                exit_code = 1;
                continue;
            }
            (stdin_str, "".to_string())
        } else {
            match fs::read_to_string(&path) {
                Ok(s) => (s, path.clone()),
                Err(err) => {
                    eprintln!("{}: {}", path, err);
                    exit_code = 1;
                    continue;
                }
            }
        };

        let (chunks, err_msg) = parse_and_transform(&display_path, &content);

        let mut transformed = render_chunks(&chunks, Mode::Transform);
        if err_msg.is_some() && !transformed.ends_with("\n\n") && !transformed.is_empty() {
            transformed.push('\n');
        }
        let has_changes = transformed != content;

        if mode == Mode::Check {
            if has_changes {
                process::exit(2);
            }
            if let Some(err) = err_msg {
                eprint!("{}", err);
                process::exit(1);
            }
            continue;
        }

        if let Some(err) = err_msg {
            eprint!("{}", err);
            exit_code = 1;
            let mut rendered = render_chunks(&chunks, mode);
            if !rendered.ends_with("\n\n") && !rendered.is_empty() {
                rendered.push('\n');
            }
            print!("{}", rendered);
            continue;
        }

        if mode == Mode::Replace {
            if path.is_empty() {
                print!("{}", transformed);
            } else if has_changes {
                if let Err(err) = fs::write(&path, &transformed) {
                    eprintln!("{}: {}", path, err);
                    exit_code = 1;
                }
            }
        } else {
            let rendered = render_chunks(&chunks, mode);
            print!("{}", rendered);
        }
    }

    process::exit(exit_code);
}

fn is_keyword(w: &str) -> bool {
    matches!(
        w,
        "if" | "then"
            | "else"
            | "elif"
            | "fi"
            | "for"
            | "do"
            | "done"
            | "while"
            | "until"
            | "case"
            | "esac"
            | "function"
            | "select"
            | "{"
            | "}"
            | "export"
            | "local"
            | "readonly"
            | "declare"
    )
}

fn parse_and_transform(path: &str, input: &str) -> (Vec<OutputChunk>, Option<String>) {
    let mut chunks = Vec::new();
    let bytes = input.as_bytes();
    let mut i = 0;
    let len = bytes.len();
    let mut command_pos = true;
    let mut is_assign_rhs = false;
    let mut in_case_head = false;
    let mut in_case_body = false;
    let mut expects_for_in = false;
    let mut for_var_next = false;
    let mut is_for_list = false;
    let mut heredoc_delimiter: Option<String> = None;
    let mut scope_stack: Vec<&'static str> = Vec::new();

    while i < len {
        // Heredoc body handling
        if let Some(ref delim) = heredoc_delimiter.clone() {
            let line_start = i;
            let line_end = input[i..].find('\n').map(|p| i + p).unwrap_or(len);
            let line_content = &input[line_start..line_end];
            let trimmed = line_content.trim_start_matches('\t');
            if trimmed == delim {
                chunks.push(OutputChunk {
                    text: line_content.to_string(),
                    diff: DiffKind::Unchanged,
                    syntax: SyntaxKind::Heredoc,
                });
                heredoc_delimiter = None;
                i = line_end;
                continue;
            } else {
                let full_line = if line_end < len { &input[line_start..line_end + 1] } else { &input[line_start..line_end] };
                chunks.push(OutputChunk {
                    text: full_line.to_string(),
                    diff: DiffKind::Unchanged,
                    syntax: SyntaxKind::Heredoc,
                });
                i = if line_end < len { line_end + 1 } else { line_end };
                continue;
            }
        }

        // Check for Syntactic Pitfall ($10, $00, $01)
        if bytes[i] == b'$' && i + 2 < len && bytes[i + 1].is_ascii_digit() && bytes[i + 2].is_ascii_digit() {
            let line_start = input[..i].rfind('\n').map(|p| p + 1).unwrap_or(0);
            let line_end = input[i..].find('\n').map(|p| i + p).unwrap_or(len);
            let line_text = &input[line_start..line_end];
            let col = i - line_start;
            let mut num_end = i + 1;
            while num_end < len && bytes[num_end].is_ascii_digit() {
                num_end += 1;
            }
            let pitfall_len = num_end - i;
            let carets = format!("{}{}", " ".repeat(col), "^".repeat(pitfall_len));

            let msg = format!(
                "{}: Unsupported syntax: Syntactic pitfall\n{}\n{}\nThis does not mean what it looks like. You may be forgiven to think that the full string of numerals is the variable name. Only the fist is.\n\nTry this and be shocked: f() {{ echo \"$9\" \"$10\"; }}; f a b c d e f g h i j\n\nHere is where braces should be used to disambiguate, e.g. \"${{10}}\" vs \"${{1}}0\".\n\nSyntactic pitfalls are deemed too dangerous to fix automatically\n(the purpose of Shellharden is to fix vulnerable code – code that mostly does what it looks like, as opposed to code that never does what it looks like):\n* Fixing what it does would be 100% subtle and might slip through code review unnoticed.\n* Fixing its look would make a likely bug look intentional.\n",
                path, line_text, carets
            );
            return (chunks, Some(msg));
        }

        // Comment / Shebang
        if bytes[i] == b'#' && (scope_stack.is_empty() || scope_stack.last() == Some(&"cmd_sub") || scope_stack.last() == Some(&"backtick")) {
            let start = i;
            while i < len && bytes[i] != b'\n' {
                i += 1;
            }
            chunks.push(OutputChunk {
                text: input[start..i].to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::Comment,
            });
            continue;
        }

        // Heredoc redirection syntax <<EOF or <<-EOF
        if bytes[i] == b'<' && i + 1 < len && bytes[i + 1] == b'<' {
            let start = i;
            i += 2;
            if i < len && bytes[i] == b'-' {
                i += 1;
            }
            while i < len && bytes[i].is_ascii_whitespace() && bytes[i] != b'\n' {
                i += 1;
            }
            let delim_start = i;
            while i < len && !bytes[i].is_ascii_whitespace() && bytes[i] != b';' {
                i += 1;
            }
            let raw_delim = &input[delim_start..i];
            let clean_delim = raw_delim.trim_matches(&['\'', '"'][..]);
            heredoc_delimiter = Some(clean_delim.to_string());

            chunks.push(OutputChunk {
                text: input[start..i].to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::Heredoc,
            });
            continue;
        }

        // Double quotes
        if bytes[i] == b'"' && scope_stack.last() != Some(&"single_quote") {
            if scope_stack.last() == Some(&"double_quote") {
                scope_stack.pop();
            } else {
                scope_stack.push("double_quote");
            }
            chunks.push(OutputChunk {
                text: "\"".to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::DoubleQuote,
            });
            i += 1;
            continue;
        }

        // Single quotes
        if bytes[i] == b'\'' && scope_stack.last() != Some(&"double_quote") {
            if scope_stack.last() == Some(&"single_quote") {
                scope_stack.pop();
            } else {
                scope_stack.push("single_quote");
            }
            chunks.push(OutputChunk {
                text: "'".to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::SingleQuote,
            });
            i += 1;
            continue;
        }

        // Inside Single Quote
        if scope_stack.last() == Some(&"single_quote") {
            let start = i;
            while i < len && bytes[i] != b'\'' {
                i += 1;
            }
            chunks.push(OutputChunk {
                text: input[start..i].to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::SingleQuote,
            });
            continue;
        }

        // Backticks
        if bytes[i] == b'`' {
            let in_dq = scope_stack.contains(&"double_quote");
            if scope_stack.last() == Some(&"backtick") {
                scope_stack.pop();
                chunks.push(OutputChunk {
                    text: "`".to_string(),
                    diff: DiffKind::Deleted,
                    syntax: SyntaxKind::None,
                });
                chunks.push(OutputChunk {
                    text: ")".to_string(),
                    diff: DiffKind::Added,
                    syntax: SyntaxKind::None,
                });
                if !in_dq {
                    chunks.push(OutputChunk {
                        text: "\"".to_string(),
                        diff: DiffKind::Added,
                        syntax: SyntaxKind::None,
                    });
                }
            } else {
                if !in_dq {
                    chunks.push(OutputChunk {
                        text: "\"".to_string(),
                        diff: DiffKind::Added,
                        syntax: SyntaxKind::None,
                    });
                }
                chunks.push(OutputChunk {
                    text: "`".to_string(),
                    diff: DiffKind::Deleted,
                    syntax: SyntaxKind::None,
                });
                chunks.push(OutputChunk {
                    text: "$(".to_string(),
                    diff: DiffKind::Added,
                    syntax: SyntaxKind::None,
                });
                scope_stack.push("backtick");
                command_pos = true;
            }
            i += 1;
            continue;
        }

        // Variable expansion
        if bytes[i] == b'$' {
            if i + 1 < len {
                let next = bytes[i + 1];
                if next == b'(' {
                    if i + 2 < len && bytes[i + 2] == b'(' {
                        // Arithmetic $(( ... ))
                        let start = i;
                        i += 3;
                        let mut paren_count = 2;
                        while i < len && paren_count > 0 {
                            if bytes[i] == b'(' {
                                paren_count += 1;
                            } else if bytes[i] == b')' {
                                paren_count -= 1;
                            }
                            i += 1;
                        }
                        chunks.push(OutputChunk {
                            text: input[start..i].to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Arithmetic,
                        });
                        continue;
                    } else {
                        // Command sub $(cmd)
                        let in_dq = scope_stack.contains(&"double_quote");
                        if !in_dq {
                            chunks.push(OutputChunk {
                                text: "\"".to_string(),
                                diff: DiffKind::Added,
                                syntax: SyntaxKind::None,
                            });
                        }
                        chunks.push(OutputChunk {
                            text: "$(".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::None,
                        });
                        i += 2;
                        scope_stack.push("cmd_sub");
                        command_pos = true;
                        continue;
                    }
                } else if next == b'{' || next.is_ascii_alphanumeric() || next == b'@' || next == b'*' || next == b'#' || next == b'?' || next == b'$' || next == b'!' || next == b'-' || next == b'_' {
                    let in_dq = scope_stack.contains(&"double_quote");
                    let mut var_end = i + 2;
                    if next == b'{' {
                        while var_end < len && bytes[var_end] != b'}' {
                            var_end += 1;
                        }
                        if var_end < len {
                            var_end += 1; // include '}'
                        }
                    } else if next.is_ascii_alphabetic() || next == b'_' || next.is_ascii_digit() {
                        if next.is_ascii_digit() {
                            var_end = i + 2;
                        } else {
                            while var_end < len && (bytes[var_end].is_ascii_alphanumeric() || bytes[var_end] == b'_') {
                                var_end += 1;
                            }
                        }
                    }

                    let orig_var = &input[i..var_end];

                    // Check for for loop array expansion
                    if is_for_list && !in_dq && !orig_var.starts_with("${") {
                        let var_name = &orig_var[1..];
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "$".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "{".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: var_name.to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "[@]}".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        i = var_end;
                        is_for_list = false;
                        continue;
                    }

                    // Check if special var $#, $?, $$, $!, ${#var}, ${!var} or inside assignment RHS or case head
                    if orig_var == "$#" || orig_var == "$?" || orig_var == "$$" || orig_var == "$!" || orig_var.starts_with("${#") || orig_var.starts_with("${!") || is_assign_rhs || in_case_head {
                        chunks.push(OutputChunk {
                            text: orig_var.to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        i = var_end;
                        continue;
                    }

                    // Check if $* -> "$@"
                    if orig_var == "$*" && !in_dq {
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "$".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "*".to_string(),
                            diff: DiffKind::Deleted,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "@".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        i = var_end;
                        continue;
                    }

                    // Check if ${var[*]} -> "${var[@]}"
                    if orig_var.ends_with("[*]}") && !in_dq {
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        let base = &orig_var[..orig_var.len() - 4];
                        chunks.push(OutputChunk {
                            text: format!("{}[", base),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "*".to_string(),
                            diff: DiffKind::Deleted,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "@".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "]}".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        i = var_end;
                        continue;
                    }

                    // Determine if braces needed
                    let char_after = if var_end < len { Some(bytes[var_end]) } else { None };
                    let needs_braces = match char_after {
                        Some(b) => {
                            if in_dq {
                                b.is_ascii_alphanumeric() || b == b'_'
                            } else {
                                b.is_ascii_alphanumeric() || b == b'_' || b == b'"'
                            }
                        }
                        None => true, // EOF
                    };

                    if in_dq {
                        if orig_var.starts_with("${") && orig_var.ends_with('}') && !needs_braces {
                            let var_name = &orig_var[2..orig_var.len() - 1];
                            chunks.push(OutputChunk {
                                text: "$".to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "{".to_string(),
                                diff: DiffKind::Deleted,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: var_name.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "}".to_string(),
                                diff: DiffKind::Deleted,
                                syntax: SyntaxKind::Variable,
                            });
                        } else {
                            chunks.push(OutputChunk {
                                text: orig_var.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                        }
                    } else {
                        // Add double quotes outside
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });

                        let var_name = if orig_var.starts_with("${") && orig_var.ends_with('}') {
                            &orig_var[2..orig_var.len() - 1]
                        } else if orig_var.starts_with('$') {
                            &orig_var[1..]
                        } else {
                            orig_var
                        };

                        if orig_var.starts_with("${") && !needs_braces {
                            chunks.push(OutputChunk {
                                text: "$".to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "{".to_string(),
                                diff: DiffKind::Deleted,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: var_name.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "}".to_string(),
                                diff: DiffKind::Deleted,
                                syntax: SyntaxKind::Variable,
                            });
                        } else if !orig_var.starts_with("${") && needs_braces {
                            chunks.push(OutputChunk {
                                text: "$".to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "{".to_string(),
                                diff: DiffKind::Added,
                                syntax: SyntaxKind::None,
                            });
                            chunks.push(OutputChunk {
                                text: var_name.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "}".to_string(),
                                diff: DiffKind::Added,
                                syntax: SyntaxKind::None,
                            });
                        } else {
                            chunks.push(OutputChunk {
                                text: orig_var.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                        }

                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                    }

                    i = var_end;
                    continue;
                }
            }
        }

        // Command substitution closing paren ')'
        if bytes[i] == b')' && scope_stack.last() == Some(&"cmd_sub") {
            scope_stack.pop();
            chunks.push(OutputChunk {
                text: ")".to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::None,
            });
            if !scope_stack.contains(&"double_quote") {
                chunks.push(OutputChunk {
                    text: "\"".to_string(),
                    diff: DiffKind::Added,
                    syntax: SyntaxKind::None,
                });
            }
            command_pos = true;
            i += 1;
            continue;
        }

        // Case closing paren ')'
        if bytes[i] == b')' && in_case_body {
            chunks.push(OutputChunk {
                text: ")".to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::None,
            });
            command_pos = true;
            i += 1;
            continue;
        }

        // Braces { and }
        if (bytes[i] == b'{' || bytes[i] == b'}') && scope_stack.is_empty() {
            let ch_str = (bytes[i] as char).to_string();
            i += 1;
            command_pos = true;
            chunks.push(OutputChunk {
                text: ch_str,
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::Keyword,
            });
            continue;
        }

        // Parsing words and operators
        let in_outer = scope_stack.is_empty() || scope_stack.last() == Some(&"cmd_sub") || scope_stack.last() == Some(&"backtick");
        if in_outer {
            if bytes[i].is_ascii_whitespace() {
                let ws_syn = if expects_for_in {
                    SyntaxKind::Keyword
                } else if in_case_head {
                    SyntaxKind::Keyword
                } else {
                    SyntaxKind::None
                };

                if bytes[i] == b'\n' || bytes[i] == b';' {
                    command_pos = true;
                    is_assign_rhs = false;
                }
                chunks.push(OutputChunk {
                    text: (bytes[i] as char).to_string(),
                    diff: DiffKind::Unchanged,
                    syntax: ws_syn,
                });
                i += 1;
                continue;
            }

            // Word token
            let start = i;
            while i < len && !bytes[i].is_ascii_whitespace() && bytes[i] != b';' && bytes[i] != b'|' && bytes[i] != b'&' && bytes[i] != b'"' && bytes[i] != b'\'' && bytes[i] != b'$' && bytes[i] != b'`' && bytes[i] != b'(' && bytes[i] != b')' {
                i += 1;
            }

            if i > start {
                let word = &input[start..i];

                if for_var_next {
                    for_var_next = false;
                    expects_for_in = true;
                    chunks.push(OutputChunk {
                        text: word.to_string(),
                        diff: DiffKind::Unchanged,
                        syntax: SyntaxKind::VarAssignName,
                    });
                    continue;
                }

                if expects_for_in {
                    if word == "in" {
                        expects_for_in = false;
                        is_for_list = true;
                        chunks.push(OutputChunk {
                            text: "in".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::None,
                        });
                        continue;
                    }
                }

                if in_case_head {
                    if word == "in" {
                        in_case_head = false;
                        in_case_body = true;
                        chunks.push(OutputChunk {
                            text: "in".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Keyword,
                        });
                        continue;
                    }
                }

                let syn = if command_pos {
                    if is_keyword(word) {
                        if word == "case" {
                            in_case_head = true;
                        } else if word == "esac" {
                            in_case_body = false;
                        } else if word == "for" || word == "select" {
                            for_var_next = true;
                        }
                        SyntaxKind::Keyword
                    } else if word.contains('=') && !word.starts_with('/') {
                        let eq_pos = word.find('=').unwrap();
                        chunks.push(OutputChunk {
                            text: word[..eq_pos].to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::VarAssignName,
                        });
                        chunks.push(OutputChunk {
                            text: "=".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::None,
                        });
                        is_assign_rhs = true;
                        command_pos = false;
                        let rhs = &word[eq_pos + 1..];
                        if !rhs.is_empty() {
                            chunks.push(OutputChunk {
                                text: rhs.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::None,
                            });
                        }
                        continue;
                    } else if in_case_body {
                        SyntaxKind::None
                    } else {
                        command_pos = false;
                        SyntaxKind::Command
                    }
                } else if word.starts_with('-') {
                    SyntaxKind::Command
                } else {
                    SyntaxKind::None
                };

                let mut word_text = word.to_string();
                if syn == SyntaxKind::Command && word == "[" && i < len && bytes[i] == b' ' {
                    word_text.push(' ');
                    i += 1;
                }

                chunks.push(OutputChunk {
                    text: word_text,
                    diff: DiffKind::Unchanged,
                    syntax: syn,
                });
                continue;
            }
        }

        // Default single char fallback
        let ch = input[i..].chars().next().unwrap();
        let ch_len = ch.len_utf8();

        let syn = if scope_stack.last() == Some(&"double_quote") {
            SyntaxKind::DoubleQuote
        } else if scope_stack.last() == Some(&"single_quote") {
            SyntaxKind::SingleQuote
        } else {
            SyntaxKind::None
        };

        chunks.push(OutputChunk {
            text: ch.to_string(),
            diff: DiffKind::Unchanged,
            syntax: syn,
        });

        i += ch_len;
    }

    // Check for unclosed scopes at EOF
    if !scope_stack.is_empty() {
        let err_msg = format!(
            "{}: Unexpected end of file\nThe file's end was reached without closing all sytactic scopes.\nEither, the parser got lost, or the file is truncated or malformed.\n",
            path
        );
        return (chunks, Some(err_msg));
    }

    (chunks, None)
}
EOF"}

{"command":"cat <<'EOF' > src/main.rs
use std::env;
use std::fs;
use std::io::{self, Read};
use std::process;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Mode {
    SyntaxSuggest,
    Syntax,
    Suggest,
    Transform,
    Check,
    Replace,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DiffKind {
    Unchanged,
    Added,
    Deleted,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SyntaxKind {
    None,
    Command,       // 38;2;192;0;128
    Keyword,       // 1
    Variable,      // 38;2;63;127;207
    VarAssignName, // 38;2;0;127;255
    SingleQuote,   // 38;2;255;204;85
    DoubleQuote,   // 38;2;255;0;0
    Arithmetic,    // 38;2;192;0;192
    Comment,       // 1;3;38;2;120;144;96
    Heredoc,       // 38;2;128;32;0
}

#[derive(Debug, Clone)]
struct OutputChunk {
    text: String,
    diff: DiffKind,
    syntax: SyntaxKind,
}

fn fg_style_code(syn: SyntaxKind) -> Option<&'static str> {
    match syn {
        SyntaxKind::None => None,
        SyntaxKind::Command => Some("38;2;192;0;128"),
        SyntaxKind::Keyword => Some("1"),
        SyntaxKind::Variable => Some("38;2;63;127;207"),
        SyntaxKind::VarAssignName => Some("38;2;0;127;255"),
        SyntaxKind::SingleQuote => Some("38;2;255;204;85"),
        SyntaxKind::DoubleQuote => Some("38;2;255;0;0"),
        SyntaxKind::Arithmetic => Some("38;2;192;0;192"),
        SyntaxKind::Comment => Some("1;3;38;2;120;144;96"),
        SyntaxKind::Heredoc => Some("38;2;128;32;0"),
    }
}

fn render_chunks(chunks: &[OutputChunk], mode: Mode) -> String {
    let mut out = String::new();
    let mut current_bg: Option<DiffKind> = None;
    let mut current_fg: SyntaxKind = SyntaxKind::None;

    for chunk in chunks {
        if chunk.text.is_empty() {
            continue;
        }

        match mode {
            Mode::Syntax => {
                if chunk.diff == DiffKind::Added {
                    continue;
                }
            }
            Mode::Transform | Mode::Check | Mode::Replace => {
                if chunk.diff == DiffKind::Deleted {
                    continue;
                }
                out.push_str(&chunk.text);
                continue;
            }
            _ => {}
        }

        let bg = match mode {
            Mode::Suggest | Mode::SyntaxSuggest => match chunk.diff {
                DiffKind::Unchanged => None,
                DiffKind::Added => Some(DiffKind::Added),
                DiffKind::Deleted => Some(DiffKind::Deleted),
            },
            _ => None,
        };

        let fg = match mode {
            Mode::Suggest => SyntaxKind::None,
            Mode::Syntax => chunk.syntax,
            Mode::SyntaxSuggest => {
                if chunk.diff == DiffKind::Unchanged {
                    chunk.syntax
                } else {
                    SyntaxKind::None
                }
            }
            _ => SyntaxKind::None,
        };

        if bg != current_bg || fg != current_fg {
            if bg.is_none() && fg == SyntaxKind::None {
                out.push_str("\x1b[m");
            } else {
                match bg {
                    Some(DiffKind::Added) => {
                        out.push_str("\x1b[0;42m");
                        if let Some(fg_code) = fg_style_code(fg) {
                            out.push_str("\x1b[0;");
                            out.push_str(fg_code);
                            out.push('m');
                        }
                    }
                    Some(DiffKind::Deleted) => {
                        out.push_str("\x1b[0;41m");
                        if let Some(fg_code) = fg_style_code(fg) {
                            out.push_str("\x1b[0;");
                            out.push_str(fg_code);
                            out.push('m');
                        }
                    }
                    None => {
                        if let Some(fg_code) = fg_style_code(fg) {
                            out.push_str("\x1b[0;");
                            out.push_str(fg_code);
                            out.push('m');
                        }
                    }
                    _ => {}
                }
            }
            current_bg = bg;
            current_fg = fg;
        }

        out.push_str(&chunk.text);
    }

    if (mode == Mode::Syntax || mode == Mode::Suggest || mode == Mode::SyntaxSuggest)
        && (current_bg.is_some() || current_fg != SyntaxKind::None)
    {
        out.push_str("\x1b[m");
    }

    out
}

const HELP_TEXT: &str = "\
Shellharden: The corrective bash syntax highlighter.

Usage:
\tshellharden [options] [files]
\tcat files | shellharden [options] ''

Shellharden is a syntax highlighter and a tool to semi-automate the rewriting
of scripts to ShellCheck conformance, mainly focused on quoting.

The default mode of operation is like `cat`, but with syntax highlighting in
foreground colors and suggestive changes in background colors.

Options:
\t--suggest         Output a colored diff suggesting changes.
\t--syntax          Output syntax highlighting with ANSI colors.
\t--syntax-suggest  Diff with syntax highlighting (default mode).
\t--transform       Output suggested changes.
\t--check           No output; exit with 2 if changes are suggested.
\t--replace         Replace file contents with suggested changes.
\t--                Don't treat further arguments as options.
\t-h|--help         Show help text.
\t--version         Show version.

The changes suggested by Shellharden inhibits word splitting and indirect
pathname expansion. This will make your script ShellCheck compliant in terms of
quoting. Whether your script will work afterwards is a different question:
If your script was using those features on purpose, it obviously won't anymore!

Every script is possible to write without using word splitting or indirect
pathname expansion, but it may involve doing things differently.
See the accompanying file how_to_do_things_safely_in_bash.md or online:
https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md
\n";

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut mode = Mode::SyntaxSuggest;
    let mut files = Vec::new();
    let mut parse_options = true;

    for arg in args.into_iter().skip(1) {
        if parse_options && arg == "--" {
            parse_options = false;
            continue;
        }
        if parse_options && arg.starts_with('-') && !arg.is_empty() {
            match arg.as_str() {
                "-h" | "--help" => {
                    print!("{}", HELP_TEXT);
                }
                "--version" => {
                    println!("4.3.1");
                }
                "--suggest" => mode = Mode::Suggest,
                "--syntax" => mode = Mode::Syntax,
                "--syntax-suggest" => mode = Mode::SyntaxSuggest,
                "--transform" => mode = Mode::Transform,
                "--check" => mode = Mode::Check,
                "--replace" => mode = Mode::Replace,
                _ => {
                    eprintln!("{}: No such option.", arg);
                    process::exit(3);
                }
            }
        } else {
            files.push(arg);
        }
    }

    if files.is_empty() {
        process::exit(0);
    }

    let mut exit_code = 0;

    for path in files {
        let (content, display_path) = if path.is_empty() {
            let mut stdin_str = String::new();
            if let Err(err) = io::stdin().read_to_string(&mut stdin_str) {
                eprintln!(": {}", err);
                exit_code = 1;
                continue;
            }
            (stdin_str, "".to_string())
        } else {
            match fs::read_to_string(&path) {
                Ok(s) => (s, path.clone()),
                Err(err) => {
                    eprintln!("{}: {}", path, err);
                    exit_code = 1;
                    continue;
                }
            }
        };

        let (chunks, err_msg) = parse_and_transform(&display_path, &content);

        let mut transformed = render_chunks(&chunks, Mode::Transform);
        if err_msg.is_some() && !transformed.ends_with("\n\n") && !transformed.is_empty() {
            transformed.push('\n');
        }
        let has_changes = transformed != content;

        if mode == Mode::Check {
            if has_changes {
                process::exit(2);
            }
            if let Some(err) = err_msg {
                eprint!("{}", err);
                process::exit(1);
            }
            continue;
        }

        if let Some(err) = err_msg {
            eprint!("{}", err);
            exit_code = 1;
            let mut rendered = render_chunks(&chunks, mode);
            if !rendered.ends_with("\n\n") && !rendered.is_empty() {
                rendered.push('\n');
            }
            print!("{}", rendered);
            continue;
        }

        if mode == Mode::Replace {
            if path.is_empty() {
                print!("{}", transformed);
            } else if has_changes {
                if let Err(err) = fs::write(&path, &transformed) {
                    eprintln!("{}: {}", path, err);
                    exit_code = 1;
                }
            }
        } else {
            let rendered = render_chunks(&chunks, mode);
            print!("{}", rendered);
        }
    }

    process::exit(exit_code);
}

fn is_keyword(w: &str) -> bool {
    matches!(
        w,
        "if" | "then"
            | "else"
            | "elif"
            | "fi"
            | "for"
            | "do"
            | "done"
            | "while"
            | "until"
            | "case"
            | "esac"
            | "function"
            | "select"
            | "{"
            | "}"
            | "export"
            | "local"
            | "readonly"
            | "declare"
    )
}

fn parse_and_transform(path: &str, input: &str) -> (Vec<OutputChunk>, Option<String>) {
    let mut chunks = Vec::new();
    let bytes = input.as_bytes();
    let mut i = 0;
    let len = bytes.len();
    let mut command_pos = true;
    let mut is_assign_rhs = false;
    let mut in_case_head = false;
    let mut in_case_body = false;
    let mut expects_for_in = false;
    let mut for_var_next = false;
    let mut is_for_list = false;
    let mut heredoc_delimiter: Option<String> = None;
    let mut scope_stack: Vec<&'static str> = Vec::new();

    while i < len {
        // Heredoc body handling
        if let Some(ref delim) = heredoc_delimiter.clone() {
            let line_start = i;
            let line_end = input[i..].find('\n').map(|p| i + p).unwrap_or(len);
            let line_content = &input[line_start..line_end];
            let trimmed = line_content.trim_start_matches('\t');
            if trimmed == delim {
                chunks.push(OutputChunk {
                    text: line_content.to_string(),
                    diff: DiffKind::Unchanged,
                    syntax: SyntaxKind::Heredoc,
                });
                heredoc_delimiter = None;
                i = line_end;
                continue;
            } else {
                let full_line = if line_end < len { &input[line_start..line_end + 1] } else { &input[line_start..line_end] };
                chunks.push(OutputChunk {
                    text: full_line.to_string(),
                    diff: DiffKind::Unchanged,
                    syntax: SyntaxKind::Heredoc,
                });
                i = if line_end < len { line_end + 1 } else { line_end };
                continue;
            }
        }

        // Check for Syntactic Pitfall ($10, $00, $01)
        if bytes[i] == b'$' && i + 2 < len && bytes[i + 1].is_ascii_digit() && bytes[i + 2].is_ascii_digit() {
            let line_start = input[..i].rfind('\n').map(|p| p + 1).unwrap_or(0);
            let line_end = input[i..].find('\n').map(|p| i + p).unwrap_or(len);
            let line_text = &input[line_start..line_end];
            let col = i - line_start;
            let mut num_end = i + 1;
            while num_end < len && bytes[num_end].is_ascii_digit() {
                num_end += 1;
            }
            let pitfall_len = num_end - i;
            let carets = format!("{}{}", " ".repeat(col), "^".repeat(pitfall_len));

            let msg = format!(
                "{}: Unsupported syntax: Syntactic pitfall\n{}\n{}\nThis does not mean what it looks like. You may be forgiven to think that the full string of numerals is the variable name. Only the fist is.\n\nTry this and be shocked: f() {{ echo \"$9\" \"$10\"; }}; f a b c d e f g h i j\n\nHere is where braces should be used to disambiguate, e.g. \"${{10}}\" vs \"${{1}}0\".\n\nSyntactic pitfalls are deemed too dangerous to fix automatically\n(the purpose of Shellharden is to fix vulnerable code – code that mostly does what it looks like, as opposed to code that never does what it looks like):\n* Fixing what it does would be 100% subtle and might slip through code review unnoticed.\n* Fixing its look would make a likely bug look intentional.\n",
                path, line_text, carets
            );
            return (chunks, Some(msg));
        }

        // Comment / Shebang
        if bytes[i] == b'#' && (scope_stack.is_empty() || scope_stack.last() == Some(&"cmd_sub") || scope_stack.last() == Some(&"backtick")) {
            let start = i;
            while i < len && bytes[i] != b'\n' {
                i += 1;
            }
            chunks.push(OutputChunk {
                text: input[start..i].to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::Comment,
            });
            continue;
        }

        // Heredoc redirection syntax <<EOF or <<-EOF
        if bytes[i] == b'<' && i + 1 < len && bytes[i + 1] == b'<' {
            let start = i;
            i += 2;
            if i < len && bytes[i] == b'-' {
                i += 1;
            }
            while i < len && bytes[i].is_ascii_whitespace() && bytes[i] != b'\n' {
                i += 1;
            }
            let delim_start = i;
            while i < len && !bytes[i].is_ascii_whitespace() && bytes[i] != b';' {
                i += 1;
            }
            let raw_delim = &input[delim_start..i];
            let clean_delim = raw_delim.trim_matches(&['\'', '"'][..]);
            heredoc_delimiter = Some(clean_delim.to_string());

            chunks.push(OutputChunk {
                text: input[start..i].to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::Heredoc,
            });
            continue;
        }

        // Double quotes
        if bytes[i] == b'"' && scope_stack.last() != Some(&"single_quote") {
            if scope_stack.last() == Some(&"double_quote") {
                scope_stack.pop();
            } else {
                scope_stack.push("double_quote");
            }
            chunks.push(OutputChunk {
                text: "\"".to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::DoubleQuote,
            });
            i += 1;
            continue;
        }

        // Single quotes
        if bytes[i] == b'\'' && scope_stack.last() != Some(&"double_quote") {
            if scope_stack.last() == Some(&"single_quote") {
                scope_stack.pop();
            } else {
                scope_stack.push("single_quote");
            }
            chunks.push(OutputChunk {
                text: "'".to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::SingleQuote,
            });
            i += 1;
            continue;
        }

        // Inside Single Quote
        if scope_stack.last() == Some(&"single_quote") {
            let start = i;
            while i < len && bytes[i] != b'\'' {
                i += 1;
            }
            chunks.push(OutputChunk {
                text: input[start..i].to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::SingleQuote,
            });
            continue;
        }

        // Backticks
        if bytes[i] == b'`' {
            let in_dq = scope_stack.contains(&"double_quote");
            if scope_stack.last() == Some(&"backtick") {
                scope_stack.pop();
                chunks.push(OutputChunk {
                    text: "`".to_string(),
                    diff: DiffKind::Deleted,
                    syntax: SyntaxKind::None,
                });
                chunks.push(OutputChunk {
                    text: ")".to_string(),
                    diff: DiffKind::Added,
                    syntax: SyntaxKind::None,
                });
                if !in_dq {
                    chunks.push(OutputChunk {
                        text: "\"".to_string(),
                        diff: DiffKind::Added,
                        syntax: SyntaxKind::None,
                    });
                }
            } else {
                if !in_dq {
                    chunks.push(OutputChunk {
                        text: "\"".to_string(),
                        diff: DiffKind::Added,
                        syntax: SyntaxKind::None,
                    });
                }
                chunks.push(OutputChunk {
                    text: "`".to_string(),
                    diff: DiffKind::Deleted,
                    syntax: SyntaxKind::None,
                });
                chunks.push(OutputChunk {
                    text: "$(".to_string(),
                    diff: DiffKind::Added,
                    syntax: SyntaxKind::None,
                });
                scope_stack.push("backtick");
                command_pos = true;
            }
            i += 1;
            continue;
        }

        // Variable expansion
        if bytes[i] == b'$' {
            if i + 1 < len {
                let next = bytes[i + 1];
                if next == b'(' {
                    if i + 2 < len && bytes[i + 2] == b'(' {
                        // Arithmetic $(( ... ))
                        let start = i;
                        i += 3;
                        let mut paren_count = 2;
                        while i < len && paren_count > 0 {
                            if bytes[i] == b'(' {
                                paren_count += 1;
                            } else if bytes[i] == b')' {
                                paren_count -= 1;
                            }
                            i += 1;
                        }
                        chunks.push(OutputChunk {
                            text: input[start..i].to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Arithmetic,
                        });
                        continue;
                    } else {
                        // Command sub $(cmd)
                        let in_dq = scope_stack.contains(&"double_quote");
                        if !in_dq {
                            chunks.push(OutputChunk {
                                text: "\"".to_string(),
                                diff: DiffKind::Added,
                                syntax: SyntaxKind::None,
                            });
                        }
                        chunks.push(OutputChunk {
                            text: "$(".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::None,
                        });
                        i += 2;
                        scope_stack.push("cmd_sub");
                        command_pos = true;
                        continue;
                    }
                } else if next == b'{' || next.is_ascii_alphanumeric() || next == b'@' || next == b'*' || next == b'#' || next == b'?' || next == b'$' || next == b'!' || next == b'-' || next == b'_' {
                    let in_dq = scope_stack.contains(&"double_quote");
                    let mut var_end = i + 2;
                    if next == b'{' {
                        while var_end < len && bytes[var_end] != b'}' {
                            var_end += 1;
                        }
                        if var_end < len {
                            var_end += 1; // include '}'
                        }
                    } else if next.is_ascii_alphabetic() || next == b'_' || next.is_ascii_digit() {
                        if next.is_ascii_digit() {
                            var_end = i + 2;
                        } else {
                            while var_end < len && (bytes[var_end].is_ascii_alphanumeric() || bytes[var_end] == b'_') {
                                var_end += 1;
                            }
                        }
                    }

                    let orig_var = &input[i..var_end];

                    // Check for for loop array expansion
                    if is_for_list && !in_dq && !orig_var.starts_with("${") {
                        let var_name = &orig_var[1..];
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "$".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "{".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: var_name.to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "[@]}".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        i = var_end;
                        is_for_list = false;
                        continue;
                    }

                    // Check if special var $#, $?, $$, $!, ${#var}, ${!var} or inside assignment RHS or case head
                    if orig_var == "$#" || orig_var == "$?" || orig_var == "$$" || orig_var == "$!" || orig_var.starts_with("${#") || orig_var.starts_with("${!") || is_assign_rhs || in_case_head {
                        chunks.push(OutputChunk {
                            text: orig_var.to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        i = var_end;
                        continue;
                    }

                    // Check if $* -> "$@"
                    if orig_var == "$*" && !in_dq {
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "$".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "*".to_string(),
                            diff: DiffKind::Deleted,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "@".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        i = var_end;
                        continue;
                    }

                    // Check if ${var[*]} -> "${var[@]}"
                    if orig_var.ends_with("[*]}") && !in_dq {
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        let base = &orig_var[..orig_var.len() - 4];
                        chunks.push(OutputChunk {
                            text: format!("{}[", base),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "*".to_string(),
                            diff: DiffKind::Deleted,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "@".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "]}".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        i = var_end;
                        continue;
                    }

                    // Determine if braces needed
                    let char_after = if var_end < len { Some(bytes[var_end]) } else { None };
                    let needs_braces = match char_after {
                        Some(b) => {
                            if in_dq {
                                b.is_ascii_alphanumeric() || b == b'_'
                            } else {
                                b.is_ascii_alphanumeric() || b == b'_' || b == b'"'
                            }
                        }
                        None => true, // EOF
                    };

                    if in_dq {
                        if orig_var.starts_with("${") && orig_var.ends_with('}') && !needs_braces {
                            let var_name = &orig_var[2..orig_var.len() - 1];
                            chunks.push(OutputChunk {
                                text: "$".to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "{".to_string(),
                                diff: DiffKind::Deleted,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: var_name.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "}".to_string(),
                                diff: DiffKind::Deleted,
                                syntax: SyntaxKind::Variable,
                            });
                        } else {
                            chunks.push(OutputChunk {
                                text: orig_var.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                        }
                    } else {
                        // Add double quotes outside
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });

                        let var_name = if orig_var.starts_with("${") && orig_var.ends_with('}') {
                            &orig_var[2..orig_var.len() - 1]
                        } else if orig_var.starts_with('$') {
                            &orig_var[1..]
                        } else {
                            orig_var
                        };

                        if orig_var.starts_with("${") && !needs_braces {
                            chunks.push(OutputChunk {
                                text: "$".to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "{".to_string(),
                                diff: DiffKind::Deleted,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: var_name.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "}".to_string(),
                                diff: DiffKind::Deleted,
                                syntax: SyntaxKind::Variable,
                            });
                        } else if !orig_var.starts_with("${") && needs_braces {
                            chunks.push(OutputChunk {
                                text: "$".to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "{".to_string(),
                                diff: DiffKind::Added,
                                syntax: SyntaxKind::None,
                            });
                            chunks.push(OutputChunk {
                                text: var_name.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "}".to_string(),
                                diff: DiffKind::Added,
                                syntax: SyntaxKind::None,
                            });
                        } else {
                            chunks.push(OutputChunk {
                                text: orig_var.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                        }

                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                    }

                    i = var_end;
                    continue;
                }
            }
        }

        // Command substitution closing paren ')'
        if bytes[i] == b')' && scope_stack.last() == Some(&"cmd_sub") {
            scope_stack.pop();
            chunks.push(OutputChunk {
                text: ")".to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::None,
            });
            if !scope_stack.contains(&"double_quote") {
                chunks.push(OutputChunk {
                    text: "\"".to_string(),
                    diff: DiffKind::Added,
                    syntax: SyntaxKind::None,
                });
            }
            command_pos = true;
            i += 1;
            continue;
        }

        // Case closing paren ')'
        if bytes[i] == b')' && in_case_body {
            chunks.push(OutputChunk {
                text: ")".to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::None,
            });
            command_pos = true;
            i += 1;
            continue;
        }

        // Braces { and }
        if (bytes[i] == b'{' || bytes[i] == b'}') && scope_stack.is_empty() {
            let ch_str = (bytes[i] as char).to_string();
            i += 1;
            command_pos = true;
            chunks.push(OutputChunk {
                text: ch_str,
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::Keyword,
            });
            continue;
        }

        // Parsing words and operators
        let in_outer = scope_stack.is_empty() || scope_stack.last() == Some(&"cmd_sub") || scope_stack.last() == Some(&"backtick");
        if in_outer {
            if bytes[i].is_ascii_whitespace() {
                let ws_syn = if expects_for_in {
                    SyntaxKind::Keyword
                } else {
                    SyntaxKind::None
                };

                if bytes[i] == b'\n' || bytes[i] == b';' {
                    command_pos = true;
                    is_assign_rhs = false;
                }
                chunks.push(OutputChunk {
                    text: (bytes[i] as char).to_string(),
                    diff: DiffKind::Unchanged,
                    syntax: ws_syn,
                });
                i += 1;
                continue;
            }

            // Word token
            let start = i;
            while i < len && !bytes[i].is_ascii_whitespace() && bytes[i] != b';' && bytes[i] != b'|' && bytes[i] != b'&' && bytes[i] != b'"' && bytes[i] != b'\'' && bytes[i] != b'$' && bytes[i] != b'`' && bytes[i] != b'(' && bytes[i] != b')' {
                i += 1;
            }

            if i > start {
                let word = &input[start..i];

                if for_var_next {
                    for_var_next = false;
                    expects_for_in = true;
                    chunks.push(OutputChunk {
                        text: word.to_string(),
                        diff: DiffKind::Unchanged,
                        syntax: SyntaxKind::VarAssignName,
                    });
                    continue;
                }

                if expects_for_in {
                    if word == "in" {
                        expects_for_in = false;
                        is_for_list = true;
                        chunks.push(OutputChunk {
                            text: "in".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::None,
                        });
                        continue;
                    }
                }

                if in_case_head {
                    if word == "in" {
                        in_case_head = false;
                        in_case_body = true;
                        chunks.push(OutputChunk {
                            text: " in".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Keyword,
                        });
                        continue;
                    }
                }

                let syn = if command_pos {
                    if is_keyword(word) {
                        if word == "case" {
                            in_case_head = true;
                            let word_text = if i < len && bytes[i] == b' ' {
                                i += 1;
                                "case ".to_string()
                            } else {
                                "case".to_string()
                            };
                            chunks.push(OutputChunk {
                                text: word_text,
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Keyword,
                            });
                            continue;
                        } else if word == "esac" {
                            in_case_body = false;
                        } else if word == "for" || word == "select" {
                            for_var_next = true;
                        }
                        SyntaxKind::Keyword
                    } else if word.contains('=') && !word.starts_with('/') {
                        let eq_pos = word.find('=').unwrap();
                        chunks.push(OutputChunk {
                            text: word[..eq_pos].to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::VarAssignName,
                        });
                        chunks.push(OutputChunk {
                            text: "=".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::None,
                        });
                        is_assign_rhs = true;
                        command_pos = false;
                        let rhs = &word[eq_pos + 1..];
                        if !rhs.is_empty() {
                            chunks.push(OutputChunk {
                                text: rhs.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::None,
                            });
                        }
                        continue;
                    } else {
                        command_pos = false;
                        SyntaxKind::Command
                    }
                } else if word.starts_with('-') {
                    SyntaxKind::Command
                } else {
                    SyntaxKind::None
                };

                let mut word_text = word.to_string();
                if syn == SyntaxKind::Command && word == "[" && i < len && bytes[i] == b' ' {
                    word_text.push(' ');
                    i += 1;
                }

                chunks.push(OutputChunk {
                    text: word_text,
                    diff: DiffKind::Unchanged,
                    syntax: syn,
                });
                continue;
            }
        }

        // Default single char fallback
        let ch = input[i..].chars().next().unwrap();
        let ch_len = ch.len_utf8();

        let syn = if scope_stack.last() == Some(&"double_quote") {
            SyntaxKind::DoubleQuote
        } else if scope_stack.last() == Some(&"single_quote") {
            SyntaxKind::SingleQuote
        } else {
            SyntaxKind::None
        };

        chunks.push(OutputChunk {
            text: ch.to_string(),
            diff: DiffKind::Unchanged,
            syntax: syn,
        });

        i += ch_len;
    }

    // Check for unclosed scopes at EOF
    if !scope_stack.is_empty() {
        let err_msg = format!(
            "{}: Unexpected end of file\nThe file's end was reached without closing all sytactic scopes.\nEither, the parser got lost, or the file is truncated or malformed.\n",
            path
        );
        return (chunks, Some(err_msg));
    }

    (chunks, None)
}
EOF"}

actions.command:
cat <<'EOF' > src/main.rs
use std::env;
use std::fs;
use std::io::{self, Read};
use std::process;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Mode {
    SyntaxSuggest,
    Syntax,
    Suggest,
    Transform,
    Check,
    Replace,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DiffKind {
    Unchanged,
    Added,
    Deleted,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SyntaxKind {
    None,
    Command,       // 38;2;192;0;128
    Keyword,       // 1
    Variable,      // 38;2;63;127;207
    VarAssignName, // 38;2;0;127;255
    SingleQuote,   // 38;2;255;204;85
    DoubleQuote,   // 38;2;255;0;0
    Arithmetic,    // 38;2;192;0;192
    Comment,       // 1;3;38;2;120;144;96
    Heredoc,       // 38;2;128;32;0
}

#[derive(Debug, Clone)]
struct OutputChunk {
    text: String,
    diff: DiffKind,
    syntax: SyntaxKind,
}

fn fg_style_code(syn: SyntaxKind) -> Option<&'static str> {
    match syn {
        SyntaxKind::None => None,
        SyntaxKind::Command => Some("38;2;192;0;128"),
        SyntaxKind::Keyword => Some("1"),
        SyntaxKind::Variable => Some("38;2;63;127;207"),
        SyntaxKind::VarAssignName => Some("38;2;0;127;255"),
        SyntaxKind::SingleQuote => Some("38;2;255;204;85"),
        SyntaxKind::DoubleQuote => Some("38;2;255;0;0"),
        SyntaxKind::Arithmetic => Some("38;2;192;0;192"),
        SyntaxKind::Comment => Some("1;3;38;2;120;144;96"),
        SyntaxKind::Heredoc => Some("38;2;128;32;0"),
    }
}

fn render_chunks(chunks: &[OutputChunk], mode: Mode) -> String {
    let mut out = String::new();
    let mut current_bg: Option<DiffKind> = None;
    let mut current_fg: SyntaxKind = SyntaxKind::None;

    for chunk in chunks {
        if chunk.text.is_empty() {
            continue;
        }

        match mode {
            Mode::Syntax => {
                if chunk.diff == DiffKind::Added {
                    continue;
                }
            }
            Mode::Transform | Mode::Check | Mode::Replace => {
                if chunk.diff == DiffKind::Deleted {
                    continue;
                }
                out.push_str(&chunk.text);
                continue;
            }
            _ => {}
        }

        let bg = match mode {
            Mode::Suggest | Mode::SyntaxSuggest => match chunk.diff {
                DiffKind::Unchanged => None,
                DiffKind::Added => Some(DiffKind::Added),
                DiffKind::Deleted => Some(DiffKind::Deleted),
            },
            _ => None,
        };

        let fg = match mode {
            Mode::Suggest => SyntaxKind::None,
            Mode::Syntax => chunk.syntax,
            Mode::SyntaxSuggest => {
                if chunk.diff == DiffKind::Unchanged {
                    chunk.syntax
                } else {
                    SyntaxKind::None
                }
            }
            _ => SyntaxKind::None,
        };

        if bg != current_bg || fg != current_fg {
            if bg.is_none() && fg == SyntaxKind::None {
                out.push_str("\x1b[m");
            } else {
                match bg {
                    Some(DiffKind::Added) => {
                        out.push_str("\x1b[0;42m");
                        if let Some(fg_code) = fg_style_code(fg) {
                            out.push_str("\x1b[0;");
                            out.push_str(fg_code);
                            out.push('m');
                        }
                    }
                    Some(DiffKind::Deleted) => {
                        out.push_str("\x1b[0;41m");
                        if let Some(fg_code) = fg_style_code(fg) {
                            out.push_str("\x1b[0;");
                            out.push_str(fg_code);
                            out.push('m');
                        }
                    }
                    None => {
                        if let Some(fg_code) = fg_style_code(fg) {
                            out.push_str("\x1b[0;");
                            out.push_str(fg_code);
                            out.push('m');
                        }
                    }
                    _ => {}
                }
            }
            current_bg = bg;
            current_fg = fg;
        }

        out.push_str(&chunk.text);
    }

    if (mode == Mode::Syntax || mode == Mode::Suggest || mode == Mode::SyntaxSuggest)
        && (current_bg.is_some() || current_fg != SyntaxKind::None)
    {
        out.push_str("\x1b[m");
    }

    out
}

const HELP_TEXT: &str = "\
Shellharden: The corrective bash syntax highlighter.

Usage:
\tshellharden [options] [files]
\tcat files | shellharden [options] ''

Shellharden is a syntax highlighter and a tool to semi-automate the rewriting
of scripts to ShellCheck conformance, mainly focused on quoting.

The default mode of operation is like `cat`, but with syntax highlighting in
foreground colors and suggestive changes in background colors.

Options:
\t--suggest         Output a colored diff suggesting changes.
\t--syntax          Output syntax highlighting with ANSI colors.
\t--syntax-suggest  Diff with syntax highlighting (default mode).
\t--transform       Output suggested changes.
\t--check           No output; exit with 2 if changes are suggested.
\t--replace         Replace file contents with suggested changes.
\t--                Don't treat further arguments as options.
\t-h|--help         Show help text.
\t--version         Show version.

The changes suggested by Shellharden inhibits word splitting and indirect
pathname expansion. This will make your script ShellCheck compliant in terms of
quoting. Whether your script will work afterwards is a different question:
If your script was using those features on purpose, it obviously won't anymore!

Every script is possible to write without using word splitting or indirect
pathname expansion, but it may involve doing things differently.
See the accompanying file how_to_do_things_safely_in_bash.md or online:
https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md
\n";

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut mode = Mode::SyntaxSuggest;
    let mut files = Vec::new();
    let mut parse_options = true;

    for arg in args.into_iter().skip(1) {
        if parse_options && arg == "--" {
            parse_options = false;
            continue;
        }
        if parse_options && arg.starts_with('-') && !arg.is_empty() {
            match arg.as_str() {
                "-h" | "--help" => {
                    print!("{}", HELP_TEXT);
                }
                "--version" => {
                    println!("4.3.1");
                }
                "--suggest" => mode = Mode::Suggest,
                "--syntax" => mode = Mode::Syntax,
                "--syntax-suggest" => mode = Mode::SyntaxSuggest,
                "--transform" => mode = Mode::Transform,
                "--check" => mode = Mode::Check,
                "--replace" => mode = Mode::Replace,
                _ => {
                    eprintln!("{}: No such option.", arg);
                    process::exit(3);
                }
            }
        } else {
            files.push(arg);
        }
    }

    if files.is_empty() {
        process::exit(0);
    }

    let mut exit_code = 0;

    for path in files {
        let (content, display_path) = if path.is_empty() {
            let mut stdin_str = String::new();
            if let Err(err) = io::stdin().read_to_string(&mut stdin_str) {
                eprintln!(": {}", err);
                exit_code = 1;
                continue;
            }
            (stdin_str, "".to_string())
        } else {
            match fs::read_to_string(&path) {
                Ok(s) => (s, path.clone()),
                Err(err) => {
                    eprintln!("{}: {}", path, err);
                    exit_code = 1;
                    continue;
                }
            }
        };

        let (chunks, err_msg) = parse_and_transform(&display_path, &content);

        let mut transformed = render_chunks(&chunks, Mode::Transform);
        if err_msg.is_some() && !transformed.ends_with("\n\n") && !transformed.is_empty() {
            transformed.push('\n');
        }
        let has_changes = transformed != content;

        if mode == Mode::Check {
            if has_changes {
                process::exit(2);
            }
            if let Some(err) = err_msg {
                eprint!("{}", err);
                process::exit(1);
            }
            continue;
        }

        if let Some(err) = err_msg {
            eprint!("{}", err);
            exit_code = 1;
            let mut rendered = render_chunks(&chunks, mode);
            if !rendered.ends_with("\n\n") && !rendered.is_empty() {
                rendered.push('\n');
            }
            print!("{}", rendered);
            continue;
        }

        if mode == Mode::Replace {
            if path.is_empty() {
                print!("{}", transformed);
            } else if has_changes {
                if let Err(err) = fs::write(&path, &transformed) {
                    eprintln!("{}: {}", path, err);
                    exit_code = 1;
                }
            }
        } else {
            let rendered = render_chunks(&chunks, mode);
            print!("{}", rendered);
        }
    }

    process::exit(exit_code);
}

fn is_keyword(w: &str) -> bool {
    matches!(
        w,
        "if" | "then"
            | "else"
            | "elif"
            | "fi"
            | "for"
            | "do"
            | "done"
            | "while"
            | "until"
            | "case"
            | "esac"
            | "function"
            | "select"
            | "{"
            | "}"
            | "export"
            | "local"
            | "readonly"
            | "declare"
    )
}

fn parse_and_transform(path: &str, input: &str) -> (Vec<OutputChunk>, Option<String>) {
    let mut chunks = Vec::new();
    let bytes = input.as_bytes();
    let mut i = 0;
    let len = bytes.len();
    let mut command_pos = true;
    let mut is_assign_rhs = false;
    let mut in_case_head = false;
    let mut in_case_body = false;
    let mut expects_for_in = false;
    let mut for_var_next = false;
    let mut is_for_list = false;
    let mut heredoc_delimiter: Option<String> = None;
    let mut scope_stack: Vec<&'static str> = Vec::new();

    while i < len {
        // Heredoc body handling
        if let Some(ref delim) = heredoc_delimiter.clone() {
            let line_start = i;
            let line_end = input[i..].find('\n').map(|p| i + p).unwrap_or(len);
            let line_content = &input[line_start..line_end];
            let trimmed = line_content.trim_start_matches('\t');
            if trimmed == delim {
                chunks.push(OutputChunk {
                    text: line_content.to_string(),
                    diff: DiffKind::Unchanged,
                    syntax: SyntaxKind::Heredoc,
                });
                heredoc_delimiter = None;
                i = line_end;
                continue;
            } else {
                let full_line = if line_end < len { &input[line_start..line_end + 1] } else { &input[line_start..line_end] };
                chunks.push(OutputChunk {
                    text: full_line.to_string(),
                    diff: DiffKind::Unchanged,
                    syntax: SyntaxKind::Heredoc,
                });
                i = if line_end < len { line_end + 1 } else { line_end };
                continue;
            }
        }

        // Check for Syntactic Pitfall ($10, $00, $01)
        if bytes[i] == b'$' && i + 2 < len && bytes[i + 1].is_ascii_digit() && bytes[i + 2].is_ascii_digit() {
            let line_start = input[..i].rfind('\n').map(|p| p + 1).unwrap_or(0);
            let line_end = input[i..].find('\n').map(|p| i + p).unwrap_or(len);
            let line_text = &input[line_start..line_end];
            let col = i - line_start;
            let mut num_end = i + 1;
            while num_end < len && bytes[num_end].is_ascii_digit() {
                num_end += 1;
            }
            let pitfall_len = num_end - i;
            let carets = format!("{}{}", " ".repeat(col), "^".repeat(pitfall_len));

            let msg = format!(
                "{}: Unsupported syntax: Syntactic pitfall\n{}\n{}\nThis does not mean what it looks like. You may be forgiven to think that the full string of numerals is the variable name. Only the fist is.\n\nTry this and be shocked: f() {{ echo \"$9\" \"$10\"; }}; f a b c d e f g h i j\n\nHere is where braces should be used to disambiguate, e.g. \"${{10}}\" vs \"${{1}}0\".\n\nSyntactic pitfalls are deemed too dangerous to fix automatically\n(the purpose of Shellharden is to fix vulnerable code – code that mostly does what it looks like, as opposed to code that never does what it looks like):\n* Fixing what it does would be 100% subtle and might slip through code review unnoticed.\n* Fixing its look would make a likely bug look intentional.\n",
                path, line_text, carets
            );
            return (chunks, Some(msg));
        }

        // Comment / Shebang
        if bytes[i] == b'#' && (scope_stack.is_empty() || scope_stack.last() == Some(&"cmd_sub") || scope_stack.last() == Some(&"backtick")) {
            let start = i;
            while i < len && bytes[i] != b'\n' {
                i += 1;
            }
            chunks.push(OutputChunk {
                text: input[start..i].to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::Comment,
            });
            continue;
        }

        // Heredoc redirection syntax <<EOF or <<-EOF
        if bytes[i] == b'<' && i + 1 < len && bytes[i + 1] == b'<' {
            let start = i;
            i += 2;
            if i < len && bytes[i] == b'-' {
                i += 1;
            }
            while i < len && bytes[i].is_ascii_whitespace() && bytes[i] != b'\n' {
                i += 1;
            }
            let delim_start = i;
            while i < len && !bytes[i].is_ascii_whitespace() && bytes[i] != b';' {
                i += 1;
            }
            let raw_delim = &input[delim_start..i];
            let clean_delim = raw_delim.trim_matches(&['\'', '"'][..]);
            heredoc_delimiter = Some(clean_delim.to_string());

            chunks.push(OutputChunk {
                text: input[start..i].to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::Heredoc,
            });
            continue;
        }

        // Double quotes
        if bytes[i] == b'"' && scope_stack.last() != Some(&"single_quote") {
            if scope_stack.last() == Some(&"double_quote") {
                scope_stack.pop();
            } else {
                scope_stack.push("double_quote");
            }
            chunks.push(OutputChunk {
                text: "\"".to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::DoubleQuote,
            });
            i += 1;
            continue;
        }

        // Single quotes
        if bytes[i] == b'\'' && scope_stack.last() != Some(&"double_quote") {
            if scope_stack.last() == Some(&"single_quote") {
                scope_stack.pop();
            } else {
                scope_stack.push("single_quote");
            }
            chunks.push(OutputChunk {
                text: "'".to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::SingleQuote,
            });
            i += 1;
            continue;
        }

        // Inside Single Quote
        if scope_stack.last() == Some(&"single_quote") {
            let start = i;
            while i < len && bytes[i] != b'\'' {
                i += 1;
            }
            chunks.push(OutputChunk {
                text: input[start..i].to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::SingleQuote,
            });
            continue;
        }

        // Backticks
        if bytes[i] == b'`' {
            let in_dq = scope_stack.contains(&"double_quote");
            if scope_stack.last() == Some(&"backtick") {
                scope_stack.pop();
                chunks.push(OutputChunk {
                    text: "`".to_string(),
                    diff: DiffKind::Deleted,
                    syntax: SyntaxKind::None,
                });
                chunks.push(OutputChunk {
                    text: ")".to_string(),
                    diff: DiffKind::Added,
                    syntax: SyntaxKind::None,
                });
                if !in_dq {
                    chunks.push(OutputChunk {
                        text: "\"".to_string(),
                        diff: DiffKind::Added,
                        syntax: SyntaxKind::None,
                    });
                }
            } else {
                if !in_dq {
                    chunks.push(OutputChunk {
                        text: "\"".to_string(),
                        diff: DiffKind::Added,
                        syntax: SyntaxKind::None,
                    });
                }
                chunks.push(OutputChunk {
                    text: "`".to_string(),
                    diff: DiffKind::Deleted,
                    syntax: SyntaxKind::None,
                });
                chunks.push(OutputChunk {
                    text: "$(".to_string(),
                    diff: DiffKind::Added,
                    syntax: SyntaxKind::None,
                });
                scope_stack.push("backtick");
                command_pos = true;
            }
            i += 1;
            continue;
        }

        // Variable expansion
        if bytes[i] == b'$' {
            if i + 1 < len {
                let next = bytes[i + 1];
                if next == b'(' {
                    if i + 2 < len && bytes[i + 2] == b'(' {
                        // Arithmetic $(( ... ))
                        let start = i;
                        i += 3;
                        let mut paren_count = 2;
                        while i < len && paren_count > 0 {
                            if bytes[i] == b'(' {
                                paren_count += 1;
                            } else if bytes[i] == b')' {
                                paren_count -= 1;
                            }
                            i += 1;
                        }
                        chunks.push(OutputChunk {
                            text: input[start..i].to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Arithmetic,
                        });
                        continue;
                    } else {
                        // Command sub $(cmd)
                        let in_dq = scope_stack.contains(&"double_quote");
                        if !in_dq {
                            chunks.push(OutputChunk {
                                text: "\"".to_string(),
                                diff: DiffKind::Added,
                                syntax: SyntaxKind::None,
                            });
                        }
                        chunks.push(OutputChunk {
                            text: "$(".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::None,
                        });
                        i += 2;
                        scope_stack.push("cmd_sub");
                        command_pos = true;
                        continue;
                    }
                } else if next == b'{' || next.is_ascii_alphanumeric() || next == b'@' || next == b'*' || next == b'#' || next == b'?' || next == b'$' || next == b'!' || next == b'-' || next == b'_' {
                    let in_dq = scope_stack.contains(&"double_quote");
                    let mut var_end = i + 2;
                    if next == b'{' {
                        while var_end < len && bytes[var_end] != b'}' {
                            var_end += 1;
                        }
                        if var_end < len {
                            var_end += 1; // include '}'
                        }
                    } else if next.is_ascii_alphabetic() || next == b'_' || next.is_ascii_digit() {
                        if next.is_ascii_digit() {
                            var_end = i + 2;
                        } else {
                            while var_end < len && (bytes[var_end].is_ascii_alphanumeric() || bytes[var_end] == b'_') {
                                var_end += 1;
                            }
                        }
                    }

                    let orig_var = &input[i..var_end];

                    // Check for for loop array expansion
                    if is_for_list && !in_dq && !orig_var.starts_with("${") {
                        let var_name = &orig_var[1..];
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "$".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "{".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: var_name.to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "[@]}".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        i = var_end;
                        is_for_list = false;
                        continue;
                    }

                    // Check if special var $#, $?, $$, $!, ${#var}, ${!var} or inside assignment RHS or case head
                    if orig_var == "$#" || orig_var == "$?" || orig_var == "$$" || orig_var == "$!" || orig_var.starts_with("${#") || orig_var.starts_with("${!") || is_assign_rhs || in_case_head {
                        chunks.push(OutputChunk {
                            text: orig_var.to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        i = var_end;
                        continue;
                    }

                    // Check if $* -> "$@"
                    if orig_var == "$*" && !in_dq {
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "$".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "*".to_string(),
                            diff: DiffKind::Deleted,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "@".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        i = var_end;
                        continue;
                    }

                    // Check if ${var[*]} -> "${var[@]}"
                    if orig_var.ends_with("[*]}") && !in_dq {
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        let base = &orig_var[..orig_var.len() - 4];
                        chunks.push(OutputChunk {
                            text: format!("{}[", base),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "*".to_string(),
                            diff: DiffKind::Deleted,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "@".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "]}".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        i = var_end;
                        continue;
                    }

                    // Determine if braces needed
                    let char_after = if var_end < len { Some(bytes[var_end]) } else { None };
                    let needs_braces = match char_after {
                        Some(b) => {
                            if in_dq {
                                b.is_ascii_alphanumeric() || b == b'_'
                            } else {
                                b.is_ascii_alphanumeric() || b == b'_' || b == b'"'
                            }
                        }
                        None => true, // EOF
                    };

                    if in_dq {
                        if orig_var.starts_with("${") && orig_var.ends_with('}') && !needs_braces {
                            let var_name = &orig_var[2..orig_var.len() - 1];
                            chunks.push(OutputChunk {
                                text: "$".to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "{".to_string(),
                                diff: DiffKind::Deleted,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: var_name.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "}".to_string(),
                                diff: DiffKind::Deleted,
                                syntax: SyntaxKind::Variable,
                            });
                        } else {
                            chunks.push(OutputChunk {
                                text: orig_var.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                        }
                    } else {
                        // Add double quotes outside
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });

                        let var_name = if orig_var.starts_with("${") && orig_var.ends_with('}') {
                            &orig_var[2..orig_var.len() - 1]
                        } else if orig_var.starts_with('$') {
                            &orig_var[1..]
                        } else {
                            orig_var
                        };

                        if orig_var.starts_with("${") && !needs_braces {
                            chunks.push(OutputChunk {
                                text: "$".to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "{".to_string(),
                                diff: DiffKind::Deleted,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: var_name.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "}".to_string(),
                                diff: DiffKind::Deleted,
                                syntax: SyntaxKind::Variable,
                            });
                        } else if !orig_var.starts_with("${") && needs_braces {
                            chunks.push(OutputChunk {
                                text: "$".to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "{".to_string(),
                                diff: DiffKind::Added,
                                syntax: SyntaxKind::None,
                            });
                            chunks.push(OutputChunk {
                                text: var_name.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                            chunks.push(OutputChunk {
                                text: "}".to_string(),
                                diff: DiffKind::Added,
                                syntax: SyntaxKind::None,
                            });
                        } else {
                            chunks.push(OutputChunk {
                                text: orig_var.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Variable,
                            });
                        }

                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                    }

                    i = var_end;
                    continue;
                }
            }
        }

        // Command substitution closing paren ')'
        if bytes[i] == b')' && scope_stack.last() == Some(&"cmd_sub") {
            scope_stack.pop();
            chunks.push(OutputChunk {
                text: ")".to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::None,
            });
            if !scope_stack.contains(&"double_quote") {
                chunks.push(OutputChunk {
                    text: "\"".to_string(),
                    diff: DiffKind::Added,
                    syntax: SyntaxKind::None,
                });
            }
            command_pos = true;
            i += 1;
            continue;
        }

        // Case closing paren ')'
        if bytes[i] == b')' && in_case_body {
            chunks.push(OutputChunk {
                text: ")".to_string(),
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::None,
            });
            command_pos = true;
            i += 1;
            continue;
        }

        // Braces { and }
        if (bytes[i] == b'{' || bytes[i] == b'}') && scope_stack.is_empty() {
            let ch_str = (bytes[i] as char).to_string();
            i += 1;
            command_pos = true;
            chunks.push(OutputChunk {
                text: ch_str,
                diff: DiffKind::Unchanged,
                syntax: SyntaxKind::Keyword,
            });
            continue;
        }

        // Parsing words and operators
        let in_outer = scope_stack.is_empty() || scope_stack.last() == Some(&"cmd_sub") || scope_stack.last() == Some(&"backtick");
        if in_outer {
            if bytes[i].is_ascii_whitespace() {
                let ws_syn = if expects_for_in {
                    SyntaxKind::Keyword
                } else {
                    SyntaxKind::None
                };

                if bytes[i] == b'\n' || bytes[i] == b';' {
                    command_pos = true;
                    is_assign_rhs = false;
                }
                chunks.push(OutputChunk {
                    text: (bytes[i] as char).to_string(),
                    diff: DiffKind::Unchanged,
                    syntax: ws_syn,
                });
                i += 1;
                continue;
            }

            // Word token
            let start = i;
            while i < len && !bytes[i].is_ascii_whitespace() && bytes[i] != b';' && bytes[i] != b'|' && bytes[i] != b'&' && bytes[i] != b'"' && bytes[i] != b'\'' && bytes[i] != b'$' && bytes[i] != b'`' && bytes[i] != b'(' && bytes[i] != b')' {
                i += 1;
            }

            if i > start {
                let word = &input[start..i];

                if for_var_next {
                    for_var_next = false;
                    expects_for_in = true;
                    chunks.push(OutputChunk {
                        text: word.to_string(),
                        diff: DiffKind::Unchanged,
                        syntax: SyntaxKind::VarAssignName,
                    });
                    continue;
                }

                if expects_for_in {
                    if word == "in" {
                        expects_for_in = false;
                        is_for_list = true;
                        chunks.push(OutputChunk {
                            text: "in".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::None,
                        });
                        continue;
                    }
                }

                if in_case_head {
                    if word == "in" {
                        in_case_head = false;
                        in_case_body = true;
                        chunks.push(OutputChunk {
                            text: " in".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Keyword,
                        });
                        continue;
                    }
                }

                let syn = if command_pos {
                    if is_keyword(word) {
                        if word == "case" {
                            in_case_head = true;
                            let word_text = if i < len && bytes[i] == b' ' {
                                i += 1;
                                "case ".to_string()
                            } else {
                                "case".to_string()
                            };
                            chunks.push(OutputChunk {
                                text: word_text,
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::Keyword,
                            });
                            continue;
                        } else if word == "esac" {
                            in_case_body = false;
                        } else if word == "for" || word == "select" {
                            for_var_next = true;
                        }
                        SyntaxKind::Keyword
                    } else if word.contains('=') && !word.starts_with('/') {
                        let eq_pos = word.find('=').unwrap();
                        chunks.push(OutputChunk {
                            text: word[..eq_pos].to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::VarAssignName,
                        });
                        chunks.push(OutputChunk {
                            text: "=".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::None,
                        });
                        is_assign_rhs = true;
                        command_pos = false;
                        let rhs = &word[eq_pos + 1..];
                        if !rhs.is_empty() {
                            chunks.push(OutputChunk {
                                text: rhs.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::None,
                            });
                        }
                        continue;
                    } else {
                        command_pos = false;
                        SyntaxKind::Command
                    }
                } else if word.starts_with('-') {
                    SyntaxKind::Command
                } else {
                    SyntaxKind::None
                };

                let mut word_text = word.to_string();
                if syn == SyntaxKind::Command && word == "[" && i < len && bytes[i] == b' ' {
                    word_text.push(' ');
                    i += 1;
                }

                chunks.push(OutputChunk {
                    text: word_text,
                    diff: DiffKind::Unchanged,
                    syntax: syn,
                });
                continue;
            }
        }

        // Default single char fallback
        let ch = input[i..].chars().next().unwrap();
        let ch_len = ch.len_utf8();

        let syn = if scope_stack.last() == Some(&"double_quote") {
            SyntaxKind::DoubleQuote
        } else if scope_stack.last() == Some(&"single_quote") {
            SyntaxKind::SingleQuote
        } else {
            SyntaxKind::None
        };

        chunks.push(OutputChunk {
            text: ch.to_string(),
            diff: DiffKind::Unchanged,
            syntax: syn,
        });

        i += ch_len;
    }

    // Check for unclosed scopes at EOF
    if !scope_stack.is_empty() {
        let err_msg = format!(
            "{}: Unexpected end of file\nThe file's end was reached without closing all sytactic scopes.\nEither, the parser got lost, or the file is truncated or malformed.\n",
            path
        );
        return (chunks, Some(err_msg));
    }

    (chunks, None)
}
