                        text: "\"".to_string(),
                        diff: DiffKind::Added,
                        syntax: SyntaxKind::None,
                    });
                }
                chunks.push(OutputChunk {
                    text: "`".to_string(),
                    diff: DiffKind::Deleted,
                    syntax: SyntaxKind::None,
                });
                chunks.push(OutputChunk {
                    text: "$(".to_string(),
                    diff: DiffKind::Added,
                    syntax: SyntaxKind::None,
