                                var_end += 1;
                            }
                        }
                    }

                    let orig_var = &input[i..var_end];

                    // Check for for loop array expansion
                    if is_for_list && !in_dq && !orig_var.starts_with("${") {
                        let var_name = &orig_var[1..];
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "$".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "{".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: var_name.to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "[@]}".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        i = var_end;
                        is_for_list = false;
                        continue;
                    }

                    // Check if special var $#, $?, $$, $!, ${#var}, ${!var} or inside assignment RHS or case head
                    if orig_var == "$#" || orig_var == "$?" || orig_var == "$$" || orig_var == "$!" || orig_var.starts_with("${#") || orig_var.starts_with("${!") || is_assign_rhs || in_case_head {
                        chunks.push(OutputChunk {
                            text: orig_var.to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
