                        i = var_end;
                        continue;
                    }

                    // Check if $* -> "$@"
                    if orig_var == "$*" && !in_dq {
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "$".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "*".to_string(),
                            diff: DiffKind::Deleted,
                            syntax: SyntaxKind::Variable,
                        });
                        chunks.push(OutputChunk {
                            text: "@".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        chunks.push(OutputChunk {
                            text: "\"".to_string(),
                            diff: DiffKind::Added,
                            syntax: SyntaxKind::None,
                        });
                        i = var_end;
                        continue;
                    }

