                i += 1;
            }

            if i > start {
                let word = &input[start..i];

                if word == "esac" {
                    in_case_body = false;
                    command_pos = true;
                    chunks.push(OutputChunk {
                        text: "esac".to_string(),
                        diff: DiffKind::Unchanged,
                        syntax: SyntaxKind::Keyword,
                    });
                    continue;
                }

                if for_var_next {
                    for_var_next = false;
                    expects_for_in = true;
                    chunks.push(OutputChunk {
                        text: word.to_string(),
                        diff: DiffKind::Unchanged,
                        syntax: SyntaxKind::VarAssignName,
                    });
                    continue;
                }

                if expects_for_in {
                    if word == "in" {
                        expects_for_in = false;
                        is_for_list = true;
                        chunks.push(OutputChunk {
                            text: "in".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::None,
                        });
                        continue;
                    }
                }

                if in_case_head {
                    if word == "in" {
                        in_case_head = false;
                        in_case_body = true;
                        command_pos = false;
                        chunks.push(OutputChunk {
                            text: "in".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::Keyword,
                        });
                        continue;
                    }
                }

                let syn = if command_pos {
                    if is_keyword(word) {
                        if word == "case" {
                            in_case_head = true;
                        } else if word == "esac" {
                            in_case_body = false;
                        } else if word == "for" || word == "select" {
                            for_var_next = true;
                        }
                        SyntaxKind::Keyword
                    } else if word.contains('=') && !word.starts_with('/') {
                        let eq_pos = word.find('=').unwrap();
                        chunks.push(OutputChunk {
                            text: word[..eq_pos].to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::VarAssignName,
                        });
                        chunks.push(OutputChunk {
                            text: "=".to_string(),
                            diff: DiffKind::Unchanged,
                            syntax: SyntaxKind::None,
                        });
                        is_assign_rhs = true;
                        command_pos = false;
                        let rhs = &word[eq_pos + 1..];
                        if !rhs.is_empty() {
                            chunks.push(OutputChunk {
                                text: rhs.to_string(),
                                diff: DiffKind::Unchanged,
                                syntax: SyntaxKind::None,
                            });
                        }
